        {
          "label": "Remove duplicate health-notice sentence only in FAQ da3bd1d7",
          "old": "<!-- wp:uagb/faq-child {\"block_id\":\"da3bd1d7\",\"question\":\"What Should I Tell You Before a Session?\",\"answer\":\"Tell me about any health conditions, medications, pregnancy, recent injury or surgery. I may adjust the work, or suggest you check with your clinician first. New numbness, weakness, unexplained swelling or radiating pain means you should see a doctor before massage.\",\"icon\":\"chevron-down\",\"iconActive\":\"chevron-up\"} /-->",
          "new": "<!-- wp:uagb/faq-child {\"block_id\":\"da3bd1d7\",\"question\":\"What Should I Tell You Before a Session?\",\"answer\":\"Tell me about any health conditions, medications, pregnancy, recent injury or surgery. I may adjust the work, or suggest you check with your clinician first.\",\"icon\":\"chevron-down\",\"iconActive\":\"chevron-up\"} /-->",
